#!/usr/bin/env python3
"""
Round 165j (culprits), 4 October 2026. Needs round 164s.

The Satellite imagery basemap's place names in its prehistoric look
(Cinzel and IM Fell English). Adds its own block to map/app.js, a test block
to map/test.mjs and the letter files in map/glyphs; changes nothing else.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 165j (4 October)\n\nNeeds round 164s (guards on its heading). No tiles patch. No app.js?v= bump.\nMade in a fifth chat (letter "j"); it adds one block of its own and touches\nno other block.\n\n- Asked 4 October: the Satellite imagery basemap\'s place names in the same\n  prehistoric look as its relief (the September paleo patches). CARTO\'s\n  picture of names is hidden on Satellite (namesRaster wrapped, satLabelsHide)\n  and names are drawn from OpenFreeMap\'s place, water_name, waterway,\n  mountain_peak and transportation_name, like old natural-history and\n  fossil-survey plates: continents, countries and regions in Cinzel (carved\n  Roman capitals), cities, towns, villages, roads and peaks in IM Fell English,\n  seas, lakes and rivers in IM Fell English Italic. Fossil bone and pale stone\n  on a dark earth halo, water pale slate blue on navy (SAT_FONT, SAT_NAME,\n  SAT_NAME_IDS outline-sat-name-*, satNameLayers, addSatNames,\n  satNamesOnTop, satNamesShow). One block ("Satellite imagery\'s own place\n  names" to its end) after Deep space\'s.\n- Letter files map/glyphs/Cinzel-Regular, Cinzel-SemiBold (instances of the\n  variable font at 400/600), IMFellEnglish-Regular, IMFellEnglish-Italic,\n  made in the sandbox (24 px SDF, buffer 3, radius 8, cutoff 0.25, ranges\n  0-8959 and 65280-65535); Satellite-names-README.md, Cinzel-OFL.txt,\n  IMFellEnglish-OFL.txt. Latin letters only (no Cyrillic or Greek), so the\n  English or Latin-letter name is shown first. setGlyphs only if none set;\n  the picture of names stays if the letters come from elsewhere\n  (SAT_GLYPHS). Place names box turns the words off; the hologram hides them\n  as it hides the others.\n- Checked: names rendered in Chromium (MapLibre 5.24) from the new letter\n  files on stand-in data. Not seen against the live tiles.\n']

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round165j: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 164s" not in h.read_text(encoding="utf-8"):
        sys.exit("round165j: round 164s must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round165j: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round165j: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round165j: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
